\n// path: test/fitur/event/operasi/event_op_supabase_test.dart\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:mockito/annotations.dart';\nimport 'package:mockito/mockito.dart';\nimport 'package:supabase_flutter/supabase_flutter.dart';\nimport 'package:wifi/fitur/event/model/event_model.dart';\nimport 'package:wifi/fitur/event/operasi/event_op_supabase.dart';\nimport 'package:wifi/shared/constant/nama_kolom.dart';\nimport 'package:wifi/shared/constant/nama_tabel.dart';\n\nimport 'event_op_supabase_test.mocks.dart';\n\n@GenerateMocks([SupabaseClient, PostgrestFilterBuilder])\nvoid main() {\n  group('EventOpSupabase', () {\n    late MockSupabaseClient mockSupabaseClient;\n    late MockPostgrestFilterBuilder mockPostgrestFilterBuilder;\n    late EventOpSupabase eventOpSupabase;\n\n    setUp(() {\n      mockSupabaseClient = MockSupabaseClient();\n      mockPostgrestFilterBuilder = MockPostgrestFilterBuilder();\n      eventOpSupabase = EventOpSupabase(supabase: mockSupabaseClient);\n\n      when(mockSupabaseClient.from(NamaTabel.event))\n          .thenReturn(mockPostgrestFilterBuilder as PostgrestQueryBuilder<PostgrestMap, PostgrestList>);\n      when(mockPostgrestFilterBuilder.select()) .thenReturn(mockPostgrestFilterBuilder);\n      when(mockPostgrestFilterBuilder.eq(any, any))\n          .thenReturn(mockPostgrestFilterBuilder);\n      when(mockPostgrestFilterBuilder.limit(any))\n          .thenReturn(mockPostgrestFilterBuilder);\n    });\n\n    final eventData = {\n      NamaKolom.id: '1',\n      NamaKolom.linkGambar: 'image.png',\n      NamaKolom.statusAktif: true,\n      NamaKolom.tanggalDibuat: DateTime.now().toIso8601String(),\n      NamaKolom.tanggalMulai: DateTime.now().toIso8601String(),\n      NamaKolom.tangglberakhir: DateTime.now().toIso8601String(),\n    };\n\n    test('01. getAll harus mengembalikan list EventModel', () async {\n      when(mockPostgrestFilterBuilder.select()).thenAnswer((_) async => [eventData]);\n\n      final result = await eventOpSupabase.getAll();\n\n      expect(result, isA<List<EventModel>>());\n      expect(result.length, 1);\n      expect(result.first.id, '1');\n    });\n\n    test('02. ambilEventAktif harus mengembalikan EventModel', () async {\n      when(mockPostgrestFilterBuilder.eq(NamaKolom.statusAktif, true)).thenAnswer((_) async => [eventData]);\n\n      final result = await eventOpSupabase.ambilEventAktif();\n\n      expect(result, isA<EventModel>());\n      expect(result?.id, '1');\n    });\n\n    test('03. ambilBerdasarkanId harus mengembalikan EventModel', () async {\n      when(mockPostgrestFilterBuilder.eq(NamaKolom.id, '1')).thenAnswer((_) async => [eventData]);\n\n      final result = await eventOpSupabase.ambilBerdasarkanId('1');\n\n      expect(result, isA<EventModel>());\n      expect(result?.id, '1');\n    });\n\n    test('04. tambahEvent harus berhasil', () async {\n      final event = EventModel.fromSupabase('1', eventData);\n       when(mockPostgrestFilterBuilder.insert(any)).thenAnswer((_) async => []);\n\n\n      await eventOpSupabase.tambahEvent(event);\n\n      verify(mockPostgrestFilterBuilder.insert(any)).called(1);\n    });\n\n    test('05. perbaruiEvent harus berhasil', () async {\n      final event = EventModel.fromSupabase('1', eventData);\n      when(mockPostgrestFilterBuilder.update(any)).thenAnswer((_) async => []);\n\n      await eventOpSupabase.perbaruiEvent(event);\n\n      verify(mockPostgrestFilterBuilder.update(any)).called(1);\n    });\n\n    test('06. hapusEvent harus berhasil', () async {\n      when(mockPostgrestFilterBuilder.delete()).thenAnswer((_) async => []);\n\n      await eventOpSupabase.hapusEvent('1');\n\n      verify(mockPostgrestFilterBuilder.delete()).called(1);\n    });\n  });\n}\n